internal fun railFontBytes(): ByteArray = decodeBase64(RAIL_FONT_BASE64)

// Kotlin has no common base64 until it is stable everywhere this builds, and a
// dependency for one decode in one test file is not worth the resolution.
private fun decodeBase64(text: String): ByteArray {
    val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    val clean: String = text.trimEnd('=')
    val out = ArrayList<Byte>(clean.length * 3 / 4)

    var buffer = 0
    var bits = 0
    for (character in clean) {
        val value: Int = alphabet.indexOf(character)
        if (value < 0) continue

        buffer = (buffer shl 6) or value
        bits += 6
        if (bits >= 8) {
            bits -= 8
            out.add(((buffer shr bits) and 0xFF).toByte())
        }
    }

    return out.toByteArray()
}
